      todo.editing = false;
    } else {
      todos = todos.filter(function (t) { return t !== todo; });
    }
    setTodos(todos);
    render();
  }

  // ── New todo ───────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: genId(),
      title: title,
      completed: false,
      editing: false,
    });
    setTodos(todos);
    render();
  }

